INSERT INTO course_resource_capability(course_id,resource_type,enabled) SELECT c.id,x.resource_type,1 FROM course c JOIN (SELECT 'concept_explanation' resource_type UNION ALL SELECT 'concept_comparison' UNION ALL SELECT 'diagram' UNION ALL SELECT 'worked_example' UNION ALL SELECT 'code_example' UNION ALL SELECT 'case_example' UNION ALL SELECT 'video_reference' UNION ALL SELECT 'guided_practice' UNION ALL SELECT 'learning_summary')x ON 1=1 ON DUPLICATE KEY UPDATE course_id=course_id;
INSERT INTO resource_generation_policy(policy_version,status,max_unit_knowledge_points,max_revision_rounds,question_similarity_threshold,config_json) VALUES('resource_policy_v1','ACTIVE',5,5,0.7200,JSON_OBJECT('allowedRelations',JSON_ARRAY('PREREQUISITE','PART_OF','RELATED_TO','SUPPORTS'))) ON DUPLICATE KEY UPDATE policy_version=policy_version;
